const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const china = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
        .filter(ee.Filter.eq('country_na', 'China'))
        .geometry();

    const startDate2000 = '2000-01-01';
    const endDate2000 = '2000-12-31';
    const startDate2017 = '2017-01-01';
    const endDate2017 = '2017-12-31';

    // 2. Data Acquisition & Check
    const modisLai = ee.ImageCollection('MODIS/006/MOD15A2H');

    const collection2000 = modisLai.filterDate(startDate2000, endDate2000).select(['Lai', 'FparLai_QC']);
    const collection2017 = modisLai.filterDate(startDate2017, endDate2017).select(['Lai', 'FparLai_QC']);

    const size2000 = await collection2000.size().getInfo();
    const size2017 = await collection2017.size().getInfo();

    if (size2000 === 0 || size2017 === 0) {
        console.log(`Image collection size for 2000: ${size2000}`);
        console.log(`Image collection size for 2017: ${size2017}`);
        console.log("Empty Collection: No images found for one or both years.");
        console.log("A"); // C1
        return;
    }

    // 3. Processing
    // Function to mask low-quality pixels and apply scale factor
    const processLai = function(image) {
        const qc = image.select('FparLai_QC');
        const qualityMask = qc.bitwiseAnd(1).eq(0); // Bit 0: 0=Good Quality
        const lai = image.select('Lai').multiply(0.1); // Apply scale factor
        return lai.updateMask(qualityMask);
    };

    const meanLai2000 = collection2000.map(processLai).mean().clip(china);
    const meanLai2017 = collection2017.map(processLai).mean().clip(china);

    const scale = 3000; // Use a coarse scale for a large area to avoid timeouts

    // 4. Calculation & Validation for C2/C3
    const statsReducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats2000 = await meanLai2000.reduceRegion({
        reducer: statsReducer,
        geometry: china,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const stats2017 = await meanLai2017.reduceRegion({
        reducer: statsReducer,
        geometry: china,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const avgLai2000 = stats2000['Lai_mean'];
    const count2000 = stats2000['Lai_count'];
    const avgLai2017 = stats2017['Lai_mean'];
    const count2017 = stats2017['Lai_count'];

    if (count2000 === 0 || count2017 === 0) {
        console.log(`Valid pixels for 2000: ${count2000}`);
        console.log(`Valid pixels for 2017: ${count2017}`);
        console.log("No Valid Pixels: 0 pixels remained after cloud/quality masking.");
        console.log("C2");
        return;
    }

    if (avgLai2000 === null || avgLai2017 === null) {
        console.log(`Average LAI for 2000: ${avgLai2000}`);
        console.log(`Average LAI for 2017: ${avgLai2017}`);
        console.log("Calculation Failure: Result is null.");
        console.log("C3");
        return;
    }

    // 5. Final Answer
    console.log(`Avg Leaf Area Index (LAI) in 2000: ${avgLai2000.toFixed(3)} (Pixels: ${count2000})`);
    console.log(`Avg Leaf Area Index (LAI) in 2017: ${avgLai2017.toFixed(3)} (Pixels: ${count2017})`);

    if (avgLai2017 > avgLai2000) {
        console.log("Conclusion: Green leaf area increased in 2017 compared to 2000.");
        console.log("A");
    } else {
        console.log("Conclusion: Green leaf area did not increase in 2017 compared to 2000.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during Earth Engine initialization or analysis.");
        console.error(e);
        console.log("D");
    }
}

initEE();
